<script setup lang="ts">import {onMounted,ref} from 'vue';import {api,messageOf} from '@/lib/api';const users=ref<any[]>([]),roles=ref<any[]>([]),companies=ref<any[]>([]),form=ref({name:'',email:'',password:'',role:'Auditor Fiscal',company_ids:[] as string[]}),error=ref('');async function load(){users.value=(await api.get('/users')).data.data;roles.value=(await api.get('/users/roles')).data;companies.value=(await api.get('/companies',{params:{per_page:100}})).data.data}onMounted(load);async function save(){try{await api.post('/users',form.value);form.value={name:'',email:'',password:'',role:'Auditor Fiscal',company_ids:[]};await load()}catch(e){error.value=messageOf(e)}}</script><template><div class="split"><section class="card"><h2>Usuários e permissões</h2><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Empresas</th><th>Ativo</th></tr></thead><tbody><tr v-for="u in users"><td>{{u.name}}</td><td>{{u.email}}</td><td>{{u.roles.map((r:any)=>r.name).join(', ')}}</td><td>{{u.companies.length}}</td><td>{{u.active?'Sim':'Não'}}</td></tr></tbody></table></section><form class="card form-grid one" @submit.prevent="save"><h2>Novo usuário</h2><label>Nome<input v-model="form.name" required/></label><label>E-mail<input v-model="form.email" type="email" required/></label><label>Senha inicial<input v-model="form.password" type="password" minlength="12" required/></label><label>Perfil<select v-model="form.role"><option v-for="r in roles">{{r.name}}</option></select></label><label>Empresas<select v-model="form.company_ids" multiple size="5"><option v-for="c in companies" :value="c.id">{{c.legal_name}}</option></select></label><p class="error" v-if="error">{{error}}</p><button class="primary">Cadastrar</button></form></div></template>
